<script setup>
import {computed,inject,nextTick,onMounted,onUnmounted,ref,shallowRef,watch} from 'vue'
import {useTheme} from 'vuetify'
import GanttEngine from '../services/gantt-engine.js'
import {createGanttData,filterGanttSurgeries,ganttFloor,GANTT_VIEWS,ganttSummary,selectGanttSurgery} from '../services/gantt-model.js'
import SurgeryJourneyPanel from '../components/SurgeryJourneyPanel.vue'
import SpatialScenePanel from '../components/SpatialScenePanel.vue'
import {buildSceneContext} from '../services/gantt-scene'
const repo=inject('repository'),theme=useTheme(),notify=inject('notify',()=>{})
const scenario=shallowRef(null),loading=ref(true),error=ref(''),host=ref(null),view=ref('patient'),date=ref(''),filtersOpen=ref(false),statsOpen=ref(true),detailsOpen=ref(false),mapOpen=ref(true),selected=shallowRef(null),cursorTime=ref(null),activeDate=ref(''),activeView=ref('patient'),locateId=ref(null),zoom=ref(1)
const fresh=()=>({departments:[],levels:[],statuses:[],priorities:[],anesthesiaTypes:[],floors:[]}),filters=ref(fresh())
let engine,dead=false
const filtered=computed(()=>filterGanttSurgeries(scenario.value?.surgeries||[],filters.value))
const activeCount=computed(()=>Object.values(filters.value).reduce((sum,values)=>sum+(values?.length||0),0))
const filterNames={departments:'科室',levels:'手术等级',statuses:'手术状态',priorities:'优先级',anesthesiaTypes:'麻醉方式',floors:'楼层'}
const options=computed(()=>{const rows=scenario.value?.surgeries||[],unique=field=>[...new Set(rows.map(s=>s[field]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'));return {departments:unique('department'),levels:['I','II','III','IV'],statuses:[...new Set(['已完成','进行中','待开始','取消',...unique('status')])],priorities:unique('priority'),anesthesiaTypes:unique('anesthesiaType'),floors:[...new Set(rows.map(ganttFloor).filter(Boolean))].sort()}})
const surgeryChoices=computed(()=>filtered.value.map(s=>({value:s.id,title:`${s.patientName} · ${s.surgeryNo} · ${s.surgeryName}`})))
const summary=computed(()=>ganttSummary(filtered.value,scenario.value?.operatingRooms?.length||40))
const statCards=computed(()=>[{label:'手术总数',value:summary.value.total,unit:'台'},{label:'已完成',value:summary.value.completed,unit:'台'},{label:'进行中',value:summary.value.inProgress,unit:'台'},{label:'待开始',value:summary.value.pending,unit:'台'},{label:'急诊手术',value:summary.value.emergency,unit:'台'},{label:'平均开始偏差',value:summary.value.avgDelay==null?'—':summary.value.avgDelay>0?'+'+summary.value.avgDelay:summary.value.avgDelay,unit:'分钟'},{label:'计划利用率',value:summary.value.utilization??'—',unit:'%'},...(scenario.value?.meta.mdtSummary?[{label:'术前 MDT 讨论率',value:scenario.value.meta.mdtSummary.discussionRate,unit:'%',caption:`完成 ${scenario.value.meta.mdtSummary.completedCount} 例 · 场景日全范围` }]:[])])
const snapshotTime=computed(()=>String(scenario.value?.meta.asOf||'14:00').match(/\d{2}:\d{2}(?::\d{2})?/)?.[0]||'14:00')
const sceneContext=computed(()=>buildSceneContext({date:activeDate.value,view:activeView.value,time:cursorTime.value||snapshotTime.value,surgery:selected.value,dark:theme.global.current.value.dark}))
const resourceInsight=computed(()=>{const s=scenario.value;if(!s)return '';if(view.value==='equipment'){const items=(s.equipment||[]).filter(e=>e.isCritical),ids=new Set(filtered.value.map(s=>s.id)),schedules=(s.equipmentSchedules||[]).filter(e=>ids.has(e.surgeryId)),minutes=t=>{const [h,m]=String(t||'0:0').split(':').map(Number);return h*60+m};return `${items.length} 台关键设备 · ${new Set(schedules.map(e=>e.equipmentId)).size} 台有排程 · ${items.filter(e=>e.status==='使用中').length} 台使用中 · ${Math.round(schedules.reduce((sum,e)=>sum+Math.max(0,minutes(e.plannedEndTime)-minutes(e.plannedStartTime)),0)/60)} 小时计划占用`}if(view.value==='pacu'){const beds=s.pacuBeds||[];return `${new Set(beds.map(b=>b.pacuRoomNo)).size} 间复苏室 · ${beds.length} 张床 · ${beds.filter(b=>b.status==='占用').length} 床占用 · ${filtered.value.filter(s=>s.recoveryStartTime&&!s.recoveryEndTime).length} 位患者复苏中`}const counts={};for(const s of filtered.value)counts[s.department]=(counts[s.department]||0)+1;return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([name,count])=>`${name} ${count} 台`).join(' · ')})
const dateRange=computed(()=>scenario.value?.meta.availableDateRange||{})
const dateError=computed(()=>{if(!scenario.value)return '';const value=date.value,stamp=new Date(value+'T12:00:00Z');return !/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(stamp.getTime())||stamp.toISOString().slice(0,10)!==value||(dateRange.value.start&&value<dateRange.value.start)||(dateRange.value.end&&value>dateRange.value.end)?'请选择场景可用日期范围内的有效日期':''})
function palette(){const dark=theme.global.current.value.dark,c=theme.global.current.value.colors,surface=dark?'#1f1f1f':'#ffffff',primary=c['primary-solid']||c.primary;return {background:surface,headerBg:dark?'#242424':'#fafafa',yAxisBg:surface,gridLine:dark?'rgba(255,255,255,.04)':'rgba(0,0,0,.035)',gridLineMajor:dark?'rgba(255,255,255,.07)':'rgba(0,0,0,.065)',headerText:dark?'#bfbfbf':'#6b6b6b',rowAlt:`rgba(${[1,3,5].map(i=>parseInt(primary.slice(i,i+2),16)).join(',')},0.08)`,subRowBg:`rgba(${[1,3,5].map(i=>parseInt(primary.slice(i,i+2),16)).join(',')},0.04)`,rowHover:dark?'rgba(255,255,255,.07)':'rgba(0,0,0,.05)',planBar:dark?'rgba(255,255,255,.12)':'rgba(0,0,0,.07)',planBarBorder:dark?'rgba(255,255,255,.32)':'rgba(0,0,0,.3)',barOverlay:dark?null:'rgba(0,0,0,0.12)',actualBar:'#6BA3FF',actualBarBorder:'#6BA3FF',selectedBorder:primary,tooltipBg:dark?'#292929':'#ffffff',tooltipText:dark?'#eeeeee':'#303030',tooltipBorder:dark?'rgba(255,255,255,.2)':'rgba(0,0,0,.15)',textPrimary:dark?'#eeeeee':'#434343',textSecondary:dark?'#bfbfbf':'#6b6b6b',deviationEarly:dark?'#34d399':'#087f5b',deviationLate:dark?'#f87171':'#c92a2a',timelineNode:{'术前':'#2e7d32','入室':'#6f49ae','麻醉':'#087e8b','手术':'#1976d2','清点':'#a76700','核查':'#24823d','标本':'#ad3374','交接':'#635ac0','出室':'#c43b3b','转运':'#1976d2','复苏':'#b96113'}}}
function clearSelection(){selected.value=null;locateId.value=null;engine?.deselect()}
function refresh(){
 if(!engine||!scenario.value||!date.value||dateError.value)return
 const keepId=selected.value?.id,data=createGanttData(scenario.value,filtered.value,view.value,date.value)
 activeDate.value=date.value;activeView.value=view.value
 engine.deselect();engine.clearSelectedTime();engine.setViewDate(date.value);engine.setData(data.rows,view.value,data.groupCatalog);engine.setEventMarkers(data.markers);engine.setTimelineEvents(data.timelineEvents)
 selected.value=selectGanttSurgery(engine,{scenario:scenario.value,surgeries:filtered.value,date:date.value},keepId)
 locateId.value=selected.value?.id||null
}
function showSurgery(s){if(!s){clearSelection();return}mapOpen.value=true;selected.value=s._raw||s;locateId.value=selected.value.id;detailsOpen.value=true}
function locate(id){
 if(!engine||!id){clearSelection();return}
 if(!filtered.value.some(s=>s.id===id))return
 selected.value=selectGanttSurgery(engine,{scenario:scenario.value,surgeries:filtered.value,date:activeDate.value},id,true)
 locateId.value=selected.value?.id||null
 if(selected.value){detailsOpen.value=true;mapOpen.value=true}
 if(selected.value&&!engine.getSelected())notify('当前资源视图没有该手术排程，详情与空间地图已同步')
}
function resetView(){engine?.resetView();zoom.value=engine?.scale||1}
function scale(factor){if(engine){engine.setScale(engine.scale*factor);zoom.value=engine.scale}}
function exportPng(){if(!engine)return;try{engine.render();const link=document.createElement('a');link.href=engine.toDataURL('image/png');link.download=`围手术期甘特图_${date.value}_${GANTT_VIEWS.find(v=>v.value===view.value)?.title}.png`;link.click();notify('已导出当前视野 PNG')}catch(e){error.value='图片导出失败：'+e.message}}
async function load(){loading.value=true;error.value='';try{const data=await repo.getScenario();if(dead)return;scenario.value=data;date.value=data.meta.date;loading.value=false;await nextTick();if(dead||!host.value)return;engine?.destroy();engine=new GanttEngine(host.value,{COLORS:palette(),PIXELS_PER_HOUR:100,now:()=>`${date.value}T${snapshotTime.value}`});engine.on('select',e=>showSurgery(e.detail.surgery));engine.on('viewport',e=>zoom.value=e.detail.scale);engine.on('timeSelect',e=>{const t=e.detail.time;cursorTime.value=t?[t.getHours(),t.getMinutes(),t.getSeconds()].map(n=>String(n).padStart(2,'0')).join(':'):null});refresh();engine.scrollToTime('08:00')}catch(e){error.value=e.message}finally{loading.value=false}}
// A cleared selection must release the detail column, including date/filter changes.
watch(selected,surgery=>{if(!surgery)detailsOpen.value=false})
watch([view,date,filtered],()=>{cursorTime.value=null;refresh()})
watch(()=>theme.global.current.value,()=>{if(engine){engine.options.COLORS={...engine.options.COLORS,...palette()};engine.render()}},{deep:true})

onMounted(load);onUnmounted(()=>{dead=true;engine?.destroy();engine=null})
</script>
<template>
<div class="page-heading"><div><h1>甘特图时序复盘</h1><p>按患者与资源对照计划、实际和全过程节点。</p></div><VChip variant="tonal" color="primary" label>确定性演示数据</VChip></div>
<VAlert v-if="error" type="error" variant="tonal" class="mb-6">{{error}}<VBtn variant="text" @click="load">重新加载</VBtn></VAlert><VProgressLinear v-if="loading" indeterminate class="mb-6"/>
<VCard v-if="scenario" class="gantt-card"><div class="gantt-top"><VTabs v-model="view" show-arrows aria-label="甘特资源视图"><VTab v-for="item in GANTT_VIEWS" :key="item.value" :value="item.value">{{item.title}}</VTab></VTabs><div class="action-row"><VBtn color="secondary" variant="text" :aria-expanded="filtersOpen" @click="filtersOpen=!filtersOpen">筛选{{activeCount?'（'+activeCount+'）':''}}</VBtn><VBtn color="secondary" variant="text" :aria-expanded="statsOpen" @click="statsOpen=!statsOpen">{{statsOpen?'收起统计':'显示统计'}}</VBtn><VBtn :disabled="!selected" :variant="detailsOpen?'tonal':'text'" :color="detailsOpen?'primary':'secondary'" :aria-pressed="detailsOpen" @click="detailsOpen=!detailsOpen">手术详情</VBtn><VBtn :variant="mapOpen?'tonal':'text'" :color="mapOpen?'primary':'secondary'" :aria-pressed="mapOpen" @click="mapOpen=!mapOpen">空间地图</VBtn><VBtn :disabled="!!dateError" @click="exportPng">导出 PNG</VBtn></div></div><VDivider/>
<div v-if="statsOpen" class="gantt-stats"><div v-for="stat in statCards" :key="stat.label"><span>{{stat.label}}</span><strong>{{stat.value}} <small>{{stat.unit}}</small></strong><span v-if="stat.caption" class="stat-scope">{{stat.caption}}</span></div></div>
<div v-if="filtersOpen" class="gantt-filters"><div class="gantt-filter-grid"><div class="filter-field" v-for="(name,key) in filterNames" :key="key"><label>{{name}}</label><VSelect v-model="filters[key]" :aria-label="'甘特筛选'+name" :items="options[key]" multiple clearable :placeholder="'全部'+name" @click:clear="filters[key]=[]"><template #selection="{item,index}"><span v-if="index===0">{{item.title}}{{filters[key]?.length>1?' 等 '+filters[key].length+' 项':''}}</span></template></VSelect></div></div><VBtn variant="text" color="secondary" @click="filters=fresh()">清除全部条件</VBtn></div>
<div class="gantt-toolbar"><div class="gantt-date"><label>复盘日期</label><VTextField type="date" v-model="date" aria-label="复盘日期" :error-messages="dateError" :min="dateRange.start||scenario.meta.date" :max="dateRange.end||scenario.meta.date"/></div><div class="gantt-locate"><label>定位患者 / 手术</label><VAutocomplete v-model="locateId" :items="surgeryChoices" aria-label="定位患者或手术" placeholder="搜索姓名、手术编号或术式" clearable @update:model-value="locate"/></div><div class="gantt-zoom"><VBtn variant="tonal" size="small" aria-label="缩小甘特图" @click="scale(1/1.2)">−</VBtn><span>{{Math.round(zoom*100)}}%</span><VBtn variant="tonal" size="small" aria-label="放大甘特图" @click="scale(1.2)">+</VBtn><VBtn variant="text" size="small" @click="resetView">重置视图</VBtn></div></div>
<div class="gantt-context"><span>{{date}} · {{filtered.length}} 台手术 · {{resourceInsight||'当前筛选范围无手术'}}</span><span class="caption">计划利用率按 {{scenario.operatingRooms?.length||40}} 间 × 14.5 小时计算</span></div><VAlert v-if="date!==scenario.meta.date" type="info" variant="tonal" class="gantt-date-note">此日期复用日内演示模板，日期按场景日平移；不是当日真实临床明细。</VAlert>
<div class="gantt-selection-bar" role="status"><span><strong>当前联动</strong> {{selected?selected.patientName+' · '+selected.surgeryNo:'未选择手术'}}{{selected?' · '+selected.operatingRoomNo:''}}</span><span>{{activeDate}} {{sceneContext.time}} · {{GANTT_VIEWS.find(v=>v.value===activeView)?.title}}视图{{activeView==='patient'?'':' · 上层计划 / 下层实际'}}</span></div>
<div class="gantt-synchronized" :class="{'without-map':!mapOpen,'without-details':!detailsOpen}"><section class="gantt-chart-pane" aria-label="甘特图面板"><div class="gantt-canvas-wrap"><div ref="host" class="gantt-canvas"/><div v-if="!filtered.length" class="gantt-no-data"><h3>暂无符合条件的手术</h3><p>调整筛选条件后查看时序记录。</p><VBtn variant="tonal" @click="filters=fresh()">清除筛选</VBtn></div></div><p class="gantt-legend-accessible">{{view==='patient'?'图例：术前准备为蓝色，转运为薄荷绿，术中为天蓝色，复苏为浅绿色。':'图例：上层虚线为计划，下层浅蓝色为实际。绿色补齐为提前，红色补齐为延时；开始与结束偏差分别计算。'}}</p></section><SurgeryJourneyPanel v-if="detailsOpen" :surgery="selected" :scenario="scenario" :view-date="activeDate" @close="detailsOpen=false"/><SpatialScenePanel v-show="mapOpen" :context="sceneContext" :scope="scenario.meta.spatialAlignment" :allowed-ids="filtered.map(s=>s.id)" @close="mapOpen=false" @select="locate"/></div>
<div class="gantt-help caption muted">Ctrl + 滚轮缩放 · 滚动 / 拖动平移 · 拖动表头复盘时间 · 双击重置 · 点击条带同步详情与空间地图 · {{view==='patient'?'患者视图按阶段着色':'上层计划 / 下层实际 · 绿色提前 / 红色延时 · 开、终分别为开始、结束偏差'}}</div><div class="gantt-foot caption muted">场景日 {{scenario.meta.date}}，快照截至 {{snapshotTime}} · 视图只读，不修改排程 · MDT 卡片不随筛选 · 导出当前可见视野</div></VCard>

</template>
<style scoped>
