ackground:rgba(var(--v-theme-surface),.95);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;padding:24px;text-align:center}.gantt-no-data h3{font-size:16px;font-weight:500}.gantt-no-data p{font-size:14px;color:rgba(var(--v-theme-on-surface),.65)}.gantt-legend{display:flex;align-items:center;flex-wrap:wrap;gap:14px;padding:16px 24px 6px;font-size:12px;line-height:20px}.gantt-legend>span{display:flex;align-items:center;gap:6px}.gantt-legend i{width:20px;height:10px;border-radius:2px}.gantt-legend .plan{border:1px dashed rgba(var(--v-theme-on-surface),.5);background:rgba(var(--v-theme-on-surface),.08)}.gantt-legend .actual{background:rgb(var(--v-theme-primary-solid))}.gantt-legend .node{width:8px;height:8px;border-radius:50%;background:rgb(var(--v-theme-success))}.gantt-foot{padding:6px 24px 20px}@media(max-width:1250px){.gantt-top{align-items:stretch;flex-direction:column;gap:8px}.gantt-top .action-row{justify-content:flex-end}.gantt-zoom{gap:4px}.gantt-toolbar{gap:12px}.gantt-context .caption{display:none}}@media(max-width:900px){.gantt-stats{grid-template-columns:repeat(4,1fr)}.gantt-toolbar{flex-wrap:wrap}.gantt-filter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.gantt-date{flex-basis:160px}.gantt-locate{max-width:none}.gantt-zoom{margin-inline-start:0}.gantt-canvas{height:540px}}
