){grid-column:1/-1}}@media(max-width:760px){.gantt-synchronized,.gantt-synchronized.without-map,.gantt-synchronized.without-details,.gantt-synchronized.without-map.without-details{grid-template-columns:minmax(0,1fr)}.gantt-toolbar{padding-inline:16px}.gantt-top .v-tabs{flex-basis:auto}.gantt-top .action-row{flex-wrap:wrap;justify-content:flex-start}}

/* Gantt workbench: group view controls, keep the timeline visually dominant. */
.gantt-card .gantt-top{padding:14px 20px;gap:12px}
.gantt-top :deep(.v-tab){min-width:76px;height:38px;border-radius:6px;font-size:14px;letter-spacing:0;margin-inline-end:4px}
.gantt-top :deep(.v-tab--selected){background:rgba(var(--v-theme-primary),.1);font-weight:600}
.gantt-top :deep(.v-tab__slider){display:none}
.gantt-top :deep(.v-tabs){height:38px}
.gantt-top .action-row :deep(.v-btn){height:34px;font-size:12px}
.gantt-toolbar{padding:18px 24px 12px;gap:20px}
